<script setup lang="ts">
import {statusLabel,metricLabel,formatMetric,weightsLabel} from '../../utils/statusLabels'
import ListPager from '../../components/ListPager.vue'
import {useListPage} from '../../composables/useListPage'
import {apiCollection} from '../../api/collections'
import { computed, nextTick, onMounted, ref, watch } from 'vue'
import { RouterLink } from 'vue-router'
import { api, ApiError, readableApiError } from '../../api/client'
import AppIcon from '../../components/AppIcon.vue'
import ServiceReadiness from '../../components/ServiceReadiness.vue'

type Mode='reviews'|'items'|'claims'|'users'|'stations'|'dictionaries'|'config'|'lab'|'reports'|'content'|'system'
const props=defineProps<{mode:Mode}>();const rows=ref<any[]>([]);const secondary=ref<any[]>([]);const summary=ref<any>(null);const loading=ref(true);const busy=ref(false);const error=ref('');const success=ref('')
const meta:Record<Mode,{id:string;title:string;lead:string}>={
 reviews:{id:'B02',title:'内容审核',lead:'协调员只能处理成员关系覆盖的站点，每次决定都记录审计事件。'},
 items:{id:'B03',title:'物品管理',lead:'审核状态与业务状态分开展示，不把关闭或归还误当作审核结果。'},
 claims:{id:'B04',title:'认领管理',lead:'查看举证状态、唯一保留与交接待办。'},
 users:{id:'B05',title:'用户管理',lead:'管理员可管理账号状态，不能停用自己的账号。'},
 stations:{id:'B06',title:'站点管理',lead:'读取真实服务站的范围、营业时间、容量与状态。'},
 dictionaries:{id:'B07',title:'字典管理',lead:'查看类别与地点字典的真实条目；版本化写操作仍需审计流程。'},
 config:{id:'B08',title:'匹配参数中心',lead:'查看可追溯的六因子权重、门槛和预处理版本，发布时生成审计记录。'},
 lab:{id:'B09',title:'算法实验室',lead:'展示固定合成基准上 B0–B3 和消融证据，不将合成指标冒充真实校园准确率。'},
 reports:{id:'B10',title:'报表中心',lead:'只展示当前权限范围内的真实数据库计数。'},
 content:{id:'B11',title:'内容运营',lead:'管理帮助文章等公共内容的发布状态。'},
 system:{id:'B12',title:'系统管理',lead:'查看健康状态与持久任务；失败任务保留错误码，刷新页面不丢失。'},
}
const page=computed(()=>meta[props.mode])
async function load(){loading.value=true;error.value='';rows.value=[];secondary.value=[];summary.value=null;try{if(props.mode==='reviews'){const response=await apiCollection<{data:{items:any[]}}>('/items/?review_status=PENDING&page_size=100');rows.value=response.data.items}else if(props.mode==='items'){const response=await apiCollection<{data:{items:any[]}}>('/items/?page_size=100');rows.value=response.data.items}else if(props.mode==='claims'){const response=await apiCollection<{data:{items:any[]}}>('/claims/?page_size=100');rows.value=response.data.items}else if(props.mode==='users'){const response=await apiCollection<{data:{items:any[]}}>('/admin/users/?page_size=100');rows.value=response.data.items}else if(props.mode==='stations'){const response=await apiCollection<{data:{items:any[]}}>('/admin/stations/?page_size=100');rows.value=response.data.items}else if(props.mode==='dictionaries'){const response=await api<{data:{categories:any[];locations:any[]}}>('/items/metadata/');rows.value=response.data.categories;secondary.value=response.data.locations}else if(props.mode==='config'){const response=await apiCollection<{data:{items:any[]}}>('/admin/matching-configs/?page_size=100');rows.value=response.data.items}else if(props.mode==='lab'){const response=await api<{data:any}>('/admin/benchmark/');summary.value=response.data}else if(props.mode==='reports'){const response=await api<{data:any}>('/admin/overview/');summary.value=response.data}else if(props.mode==='content'){const response=await apiCollection<{data:{items:any[]}}>('/admin/help/?page_size=100');rows.value=response.data.items}else{const [health,tasks]=await Promise.all([api<{data:any}>('/health/'),apiCollection<{data:{items:any[]}}>('/admin/tasks/?page_size=100')]);summary.value=health.data;rows.value=tasks.data.items}}catch(reason){error.value=readableApiError(reason,'管理数据加载失败')}finally{loading.value=false}}
const reviewItem=ref<any>(null),reviewOpen=ref(false),reviewLoading=ref(false),reviewNote=ref(''),reviewDecision=ref('APPROVE'),reviewError=ref('')
const reviewPanel=ref<HTMLElement>()
let previousReviewFocus:HTMLElement|null=null
watch(reviewOpen,async open=>{if(open){previousReviewFocus=document.activeElement as HTMLElement;await nextTick();reviewPanel.value?.querySelector<HTMLButtonElement>('button')?.focus()}else previousReviewFocus?.focus()})
function reviewKeys(event:KeyboardEvent){if(event.key==='Escape'&&!busy.value){event.preventDefault();reviewOpen.value=false;return}if(event.key!=='Tab')return;const nodes=[...(reviewPanel.value?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href]')??[])].filter(node=>node.getBoundingClientRect().width>0);const first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}}
async function openReview(entry:any){reviewOpen.value=true;reviewLoading.value=true;reviewItem.value=null;reviewNote.value='';reviewDecision.value='APPROVE';reviewError.value='';try{reviewItem.value=(await api<{data:any}>(`/items/${entry.id}/`)).data}catch(reason){reviewError.value=readableApiError(reason,'审核材料读取失败，请重试')}finally{reviewLoading.value=false}}
async function review(){if(!reviewItem.value||busy.value)return;reviewError.value='';if(reviewDecision.value==='REJECT'&&reviewNote.value.trim().length<5){reviewError.value='请填写至少5个字的具体驳回原因';return}busy.value=true;try{await api(`/items/${reviewItem.value.id}/review/`,{method:'POST',body:JSON.stringify({decision:reviewDecision.value,note:reviewNote.value.trim()||'已核对发布内容与照片'})});success.value='审核决定已记录';reviewOpen.value=false;await load()}catch(reason){reviewError.value=readableApiError(reason,'审核失败，请重试')}finally{busy.value=false}}
async function toggleUser(entry:any){busy.value=true;try{const target=entry.account_status==='ACTIVE'?'SUSPENDED':'ACTIVE';await api(`/admin/users/${entry.id}/`,{method:'PATCH',body:JSON.stringify({account_status:target})});await load()}catch(reason){error.value=readableApiError(reason,'用户更新失败')}finally{busy.value=false}}
async function publishConfig(id:number){busy.value=true;try{await api(`/admin/matching-configs/${id}/publish/`,{method:'POST'});success.value='算法配置已发布并记录审计';await load()}catch(reason){error.value=readableApiError(reason,'发布失败')}finally{busy.value=false}}
async function toggleContent(entry:any){busy.value=true;try{await api(`/admin/help/${entry.id}/`,{method:'PATCH',body:JSON.stringify({is_published:!entry.is_published,published_at:!entry.is_published?new Date().toISOString():entry.published_at})});await load()}catch(reason){error.value=readableApiError(reason,'内容更新失败')}finally{busy.value=false}}
onMounted(load);watch(()=>props.mode,load)

const {page:pagedRowsPage,rows:pagedRows}=useListPage(rows)
</script>
<template><div class="page admin-resource"><header><div><h1 class="page-title">{{page.title}}</h1><p class="page-lead">{{page.lead}}</p></div><RouterLink class="button button-ghost" to="/admin/overview">返回总览</RouterLink></header><ServiceReadiness v-if="mode==='system'"/><p v-if="success" class="notice success">{{success}}</p><p v-if="loading" class="state">正在读取权限范围内的真实数据…</p><p v-else-if="error" class="state error">{{error}}</p><template v-else><section v-if="mode==='lab'&&summary" class="lab"><div class="panel lab-summary"><p class="eyebrow">固定演示评测</p><h2>{{summary.model_version}}</h2><dl><div><dt>测试查询</dt><dd>{{summary.test_query_count}}</dd></div><div><dt>候选</dt><dd>{{summary.candidate_count}}</dd></div><div><dt>资格召回</dt><dd>{{(summary.candidate_eligibility_recall*100).toFixed(0)}}%</dd></div></dl><p>{{summary.limitations.join(' ')}}</p></div><div class="method-grid"><article v-for="(value,key) in summary.methods" :key="key" class="panel"><span>{{key}}</span><strong>MRR {{value.metrics.mrr.toFixed(3)}}</strong><small>Hit@1 {{value.metrics['hit@1'].toFixed(3)}} · n={{value.query_count}}</small></article></div></section><section v-else-if="mode==='reports'&&summary" class="report-grid"><article v-for="(value,key) in summary" :key="key" class="panel report-card"><span>{{metricLabel(key)}}</span><strong v-if="typeof value!=='object'">{{formatMetric(value)}}</strong><p v-else>{{formatMetric(value)}}</p></article></section><section v-else-if="mode==='dictionaries'" class="dict-grid"><div class="panel"><h2>类别字典 · {{rows.length}}</h2><div class="chips"><span v-for="entry in pagedRows" :key="entry.id">{{entry.name}} <small>{{entry.code}}</small></span></div></div><div class="panel"><h2>地点字典 · {{secondary.length}}</h2><div class="chips"><span v-for="entry in secondary" :key="entry.id">{{entry.name}} <small>{{entry.code}}</small></span></div></div></section><section v-else class="data-table"><article v-for="entry in pagedRows" :key="entry.id" class="panel data-row"><template v-if="mode==='reviews'||mode==='items'"><div><span>{{statusLabel(entry.kind)}} · {{statusLabel(entry.review_status)}}</span><h2>{{entry.title}}</h2><p>{{entry.category_name}} · {{entry.location_name}} · {{statusLabel(entry.business_status)}}</p></div><div v-if="mode==='reviews'" class="actions"><button class="button button-brand" :disabled="busy" @click="openReview(entry)">查看审核材料</button></div><RouterLink v-else :to="`/items/${entry.id}`">查看 <AppIcon name="arrow"/></RouterLink></template><template v-else-if="mode==='claims'"><div><span>{{statusLabel(entry.status)}}</span><h2>{{entry.item_title}}</h2><p>{{entry.statement}}</p></div><RouterLink :to="`/claims/${entry.id}`">处理 <AppIcon name="arrow"/></RouterLink></template><template v-else-if="mode==='users'"><div><span>{{statusLabel(entry.role)}} · {{statusLabel(entry.account_status)}}</span><h2>{{entry.display_name}}</h2><p>@{{entry.username}} · {{entry.email||'无邮箱'}}</p></div><button class="button button-ghost" :disabled="busy" @click="toggleUser(entry)">{{entry.account_status==='ACTIVE'?'停用':'恢复'}}</button></template><template v-else-if="mode==='stations'"><div><span>{{statusLabel(entry.status)}}</span><h2>{{entry.name}}</h2><p>{{entry.location.name}} · {{entry.address}} · 容量 {{entry.capacity}}</p></div><RouterLink :to="`/stations/${entry.id}`">查看 <AppIcon name="arrow"/></RouterLink></template><template v-else-if="mode==='config'"><div><span>{{entry.is_published?'已发布':'草案'}} · {{entry.version}}</span><h2>{{entry.name}}</h2><p>{{weightsLabel(entry.weights)}}</p></div><button v-if="!entry.is_published" class="button button-brand" :disabled="busy" @click="publishConfig(entry.id)">发布</button></template><template v-else-if="mode==='content'"><div><span>{{entry.is_published?'已发布':'未发布'}} · {{entry.category}}</span><h2>{{entry.title}}</h2><p>{{entry.body}}</p></div><button class="button button-ghost" :disabled="busy" @click="toggleContent(entry)">{{entry.is_published?'下架':'发布'}}</button></template><template v-else><div><span>{{statusLabel(entry.status)}} · {{entry.task_type}}</span><h2>任务 #{{entry.id}}</h2><p>{{entry.error_code||'无错误码'}} · {{entry.error_message||'正常'}}</p></div><strong>{{entry.progress}}%</strong></template></article><div v-if="!rows.length" class="empty">当前权限范围内没有对应数据。</div></section></template><Teleport to="body"><div v-if="reviewOpen" class="review-backdrop" @click.self="!busy&&(reviewOpen=false)"><section ref="reviewPanel" class="review-dialog" role="dialog" aria-modal="true" aria-label="发布内容审核" @keydown="reviewKeys"><header><h2>发布内容审核</h2><button type="button" :disabled="busy" aria-label="关闭审核材料" @click="reviewOpen=false">关闭</button></header><p v-if="reviewLoading" role="status">正在读取完整材料…</p><p v-if="reviewError" class="error" role="alert">{{reviewError}}</p><form v-if="reviewItem" @submit.prevent="review"><h3>{{reviewItem.title}}</h3><p>{{reviewItem.owner_display_name}} · {{reviewItem.category_name}} · {{reviewItem.location_name}}</p><p class="review-description">{{reviewItem.description}}</p><div class="review-photos"><img v-for="photo in reviewItem.media" :key="photo.id" :src="photo.file" :alt="reviewItem.title+'的附件照片'"/></div><p v-if="reviewItem.image_note">{{reviewItem.image_note}}</p><label>审核决定<select v-model="reviewDecision" aria-label="审核决定"><option value="APPROVE">通过</option><option value="REJECT">驳回</option></select></label><label>审核说明<textarea aria-label="审核说明" v-model="reviewNote" :required="reviewDecision==='REJECT'" :minlength="reviewDecision==='REJECT'?5:0" maxlength="500" :placeholder="reviewDecision==='REJECT'?'说明需要修改的具体内容':'已核对内容与照片'"/></label><button class="button button-brand" :disabled="busy">{{busy?'正在提交…':'确认提交审核决定'}}</button></form></section></div></Teleport><ListPager :page="pagedRowsPage" :total="rows.length" @change="pagedRowsPage=$event"/></div></template>
<style scoped>
.review-backdrop{position:fixed;inset:0;z-index:110;background:#14254480;display:grid;place-items:center;padding:20px}.review-dialog{width:min(720px,100%);max-height:90dvh;overflow:auto;border-radius:20px;padding:24px;background:white}.review-dialog header{display:flex;justify-content:space-between;align-items:center}.review-dialog form{display:grid;gap:18px}.review-dialog label{display:grid;gap:8px}.review-dialog select,.review-dialog textarea{width:100%;padding:12px;border:1px solid var(--ct-border);border-radius:10px;font:inherit}.review-description{white-space:pre-wrap;overflow-wrap:anywhere}.review-photos{display:flex;flex-wrap:wrap;gap:12px}.review-photos img{max-width:100%;width:200px;max-height:260px;object-fit:contain}
.admin-resource>header{display:flex;justify-content:space-between;align-items:end;gap:25px}.notice,.state{padding:14px;border-radius:10px}.success{color:var(--ct-success);background:rgba(54,100,75,.07)}.state{display:grid;place-items:center;min-height:320px}.error{color:var(--ct-danger)}.data-table{display:grid;gap:10px;margin-top:34px}.data-row{display:flex;justify-content:space-between;align-items:center;gap:20px;padding:20px;box-shadow:none}.data-row span,.data-row p{color:var(--ct-text-muted)}.data-row h2,.data-row p{margin:5px 0}.data-row a{display:flex;align-items:center;gap:6px;color:var(--ct-brand)}.actions{display:flex;gap:8px}.dict-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:34px}.dict-grid>.panel{padding:24px}.chips{display:flex;flex-wrap:wrap;gap:8px}.chips>span{padding:9px;border:1px solid var(--ct-border);border-radius:9px}.chips small{color:var(--ct-text-muted)}.lab{margin-top:34px}.lab-summary{padding:26px}.lab-summary dl{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:var(--ct-border)}.lab-summary dl div{padding:16px;background:var(--ct-bg-soft)}.lab-summary dt{color:var(--ct-text-muted)}.lab-summary dd{margin:5px 0;color:var(--ct-brand);font-size:26px}.lab-summary>p{color:var(--ct-text-muted);line-height:1.7}.method-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-top:12px}.method-grid article{padding:18px}.method-grid span,.method-grid strong,.method-grid small{display:block}.method-grid span,.method-grid small{color:var(--ct-text-muted);font-size:10px}.method-grid strong{margin:9px 0;color:var(--ct-brand)}.report-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:34px}.report-card{padding:20px}.report-card span{color:var(--ct-text-muted)}.report-card strong{display:block;margin-top:8px;color:var(--ct-brand);font-size:28px}.report-card pre{overflow:auto;font-size:10px}.empty{padding:60px;color:var(--ct-text-muted);border:1px dashed var(--ct-border);border-radius:15px;text-align:center}@media(max-width:850px){.method-grid,.report-grid{grid-template-columns:1fr 1fr}.dict-grid{grid-template-columns:1fr}}@media(max-width:600px){.admin-resource>header{align-items:start;flex-direction:column}.data-row{align-items:start;flex-direction:column}.method-grid,.report-grid{grid-template-columns:1fr}}</style>
